INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33011, 'Luke 5:5', 'Luke', 5, 5, 'شمعون ورته په ځواب کې وویل: «ای باداره! مونږ ټوله شپه خواري وکړه او هېڅ مو ونه نیول. خو که چېرې ته وایې، نو زه به جالونه ورواچوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_5.mp3', '', 1761754199, 1761754199),
(33012, 'Luke 5:6', 'Luke', 5, 6, 'هغوی همداسې وکړل او دومره زیات ماهیان یې ونیول چې نژدې ؤ جالونه وشلیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_6.mp3', '', 1761754199, 1761754199),
(33013, 'Luke 5:7', 'Luke', 5, 7, 'نو هغوی خپلو ملګرو ته چې په بلې کشتۍ کې وو، اشاره وکړه چې راشي او مرسته ورسره وکړي. هغوی راغلل او دواړه کشتۍ یې له ماهیانو څخه داسې ډکې کړې چې نژدې وې ډوبې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_7.mp3', '', 1761754199, 1761754199),
(33014, 'Luke 5:8', 'Luke', 5, 8, 'کله چې شمعون پطروس ولیدل چې څه وشول، هغه د عیسی پښو ته پرېوت او ویې ویل: «ای پاکه استاذه! زما څخه لېرې شه. ځکه چې زه یو ګناهکار انسان یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_8.mp3', '', 1761754199, 1761754199),
(33015, 'Luke 5:9', 'Luke', 5, 9, 'پطروس او ټول ملګري یې د دومره زیاتو ماهیانو په نیولو حیران پاتې شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_9.mp3', '', 1761754199, 1761754199),
(33016, 'Luke 5:10', 'Luke', 5, 10, 'همدارنګه د شمعون شریکان یعقوب او یوحنا چې د زبدي زامن وو، هم حیران شول. عیسی شمعون ته وویل: «مه وېرېږه، له دې وروسته به ته ماهیان نه بلکې انسانان رانیسې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_10.mp3', '', 1761754199, 1761754199),
(33017, 'Luke 5:11', 'Luke', 5, 11, 'کله چې هغوی خپلې کشتۍ وچې ته راوستلې، نو هرڅه یې پرېښودل او د عیسی پسې روان شول. عیسی یو جذامي ته شفا ورکوي (متي ۸‏:‌۱‌‏-‌۴ او مرقوس ۱‏:‌۴۰‌‏-‌۴۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_11.mp3', '', 1761754199, 1761754199),
(33018, 'Luke 5:12', 'Luke', 5, 12, 'یوځل عیسی په یو ښار کې ؤ، هلته یو سړی ؤ چې د جذام په ناروغۍ اخته ؤ. کله چې هغه سړي عیسی ولیده، نو په پښو کې یې پرېوت او زارۍ یې ورته وکړې: «ای ښاغلیه‎! که چېرې ته وغواړې، نو کولای شې چې ما پاک او روغ کړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_12.mp3', '', 1761754199, 1761754199),
(33019, 'Luke 5:13', 'Luke', 5, 13, 'عیسی خپل لاس وراوږد کړ او په هغه باندې یې کېښود او ویې ویل: «هو، زه غواړم، پاک او روغ شه.» نو هغه ناروغي سمدلاسه ورڅخه لېرې شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_13.mp3', '', 1761754199, 1761754199),
(33020, 'Luke 5:14', 'Luke', 5, 14, 'عیسی هغه ته امر وکړ: «په دې هکله هېچا ته څه ونه وایې، خو لاړ شه او کاهن ته خپل ځان وروښایه او کومه قرباني چې موسی یې حکم کړی دی وړاندې کړه، د دې دپاره چې خلکو ته ثابته شي چې ته پاک او روغ شوی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_14.mp3', '', 1761754199, 1761754199),
(33021, 'Luke 5:15', 'Luke', 5, 15, 'خو د عیسی په هکله خبر نور هم زیات خپور شو او ډېر خلک راغلل چې د هغه خبرې واوري او د خپلو ناروغیو څخه شفا ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_15.mp3', '', 1761754199, 1761754199),
(33022, 'Luke 5:16', 'Luke', 5, 16, 'خو هغه به ګوښه ځایونو ته تللو چې هلته دعا وکړي. عیسی یو شل سړي ته شفا ورکوي (متي ۹‏:‌۱‌‏-‌۸ او مرقوس ۲‏:‌۱‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_16.mp3', '', 1761754199, 1761754199),
(33023, 'Luke 5:17', 'Luke', 5, 17, 'یوه ورځ کله چې عیسی تعلیم ورکاوه، ځینې فریسیان او د شریعت عالمان چې د جلیل د هر کلي، یهودیې او اورشلیم څخه راغلي وو، هلته ناست وو او عیسی د خدای په قدرت سره ناروغان روغول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_17.mp3', '', 1761754199, 1761754199),
(33024, 'Luke 5:18', 'Luke', 5, 18, 'په دې وخت کې څو کسانو یو شل سړی په کټ کې راوړ. هغوی هڅه کوله چې هغه دننه کور ته بوځي او د عیسی په مخکې یې کېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_18.mp3', '', 1761754199, 1761754199),
(33025, 'Luke 5:19', 'Luke', 5, 19, 'خو د ګڼې‌ګوڼې له امله یې لاره ونه موندله ترڅو هغه دننه بوځي. نو هغه شل سړی یې پاس بام ته پورته کړ، د پخو خښتو په منځ کې یې یو سوری جوړ کړ او هغه یې په کټ کې لاندې راښکته کړ او د ګڼې‌ګوڼې په منځ کې یې د عیسی په مخکې کېښود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_19.mp3', '', 1761754199, 1761754199),
(33026, 'Luke 5:20', 'Luke', 5, 20, 'کله چې عیسی د هغوی ایمان ولیده، نو هغه سړي ته یې وویل: «وروره! ستا ګناهونه وبخښل شول.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_20.mp3', '', 1761754199, 1761754199),
(33027, 'Luke 5:21', 'Luke', 5, 21, 'هغه وخت د شریعت عالمانو او فریسیانو یو له بله سره بحث پیل کړ: «دا سړی څوک دی چې کفر وایي؟ ایا بې له خدایه څوک کولای شي چې ګناهونه وبخښي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_21.mp3', '', 1761754199, 1761754199),
(33028, 'Luke 5:22', 'Luke', 5, 22, 'عیسی د هغوی په خیالونو پوه شو او ورته ویې ویل: «تاسو ولې په خپلو زړونو کې داسې فکرونه کوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_22.mp3', '', 1761754199, 1761754199),
(33029, 'Luke 5:23', 'Luke', 5, 23, 'ایا دا خبره اسانه ده چې وویل شي چې ستا ګناهونه وبخښل شول یا وویل شي چې پاڅېږه او وګرځه؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_23.mp3', '', 1761754199, 1761754199),
(33030, 'Luke 5:24', 'Luke', 5, 24, 'خو زه به تاسو ته ثابته کړم چې د انسان زوی د ځمکې په مخ دا اختیار لري چې ګناهونه وبخښي.» نو هغه شل سړي ته یې وویل: «زه تاته وایم پاڅېږه، کټ دې واخله او خپل کور ته لاړ شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_24.mp3', '', 1761754199, 1761754199),
(33031, 'Luke 5:25', 'Luke', 5, 25, 'نو سمدلاسه هغه سړی د ټولو خلکو په مخکې پاڅېد، خپل کټ یې چې ورباندې پروت ؤ واخیست او په داسې حال کې چې د خدای ثنا یې ویله، خپل کور ته روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_25.mp3', '', 1761754199, 1761754199),
(33032, 'Luke 5:26', 'Luke', 5, 26, 'هغوی ټول حیران پاتې شول، وېرې واخیستل او د خدای ثنا او صفت یې کاوه او ویل یې: «مونږ نن څه حیرانوونکي شیان ولیدل.» عیسی لاوي خپل شاګرد ټاکي (متي ۹‏:‌۹‌‏-‌۱۳ او مرقوس ۲‏:‌۱۳‌‏-‌۱۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_26.mp3', '', 1761754199, 1761754199),
(33033, 'Luke 5:27', 'Luke', 5, 27, 'له هغې وروسته عیسی دباندې ووت او د لاوي په نوم یو مالیه ټولوونکی یې ولیده چې د مالیې راټولولو په ځای کې ناست ؤ. عیسی هغه ته وویل: «ما پسې راځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_27.mp3', '', 1761754199, 1761754199),
(33034, 'Luke 5:28', 'Luke', 5, 28, 'لاوي راپاڅېد، هرڅه یې پرېښودل او په هغه پسې روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_28.mp3', '', 1761754199, 1761754199),
(33035, 'Luke 5:29', 'Luke', 5, 29, 'بیا لاوي په خپل کور کې د عیسی دپاره یوه لویه مېلمستیا جوړه کړه او په مېلمنو کې زیات شمېر مالیه ټولوونکي او نور خلک هم وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_29.mp3', '', 1761754199, 1761754199),
(33036, 'Luke 5:30', 'Luke', 5, 30, 'خو ځینو فریسیانو او د شریعت عالمان چې د هغوی د ډلې څخه وو د عیسی په شاګردانو اعتراض وکړ او پوښتنه یې وکړه: «تاسو ولې د مالیه ټولوونکو او نورو ګناهکارانو سره یوځای خورئ او څښئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_30.mp3', '', 1761754199, 1761754199),
(33037, 'Luke 5:31', 'Luke', 5, 31, 'عیسی ورته په ځواب کې وویل: «روغ خلک ډاکتر ته اړتیا نه لري، بلکې ناروغان ورته اړتیا لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_31.mp3', '', 1761754199, 1761754199),
(33038, 'Luke 5:32', 'Luke', 5, 32, 'زه د پرهېزګارانو دپاره نه یم راغلی، بلکې د ګناهکارانو دپاره ترڅو هغوی توبه وباسي.» د روژې په هکله پوښتنه (متي ۹‏:‌۱۴‌‏-‌۱۷ او مرقوس ۲‏:‌۱۸‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_32.mp3', '', 1761754199, 1761754199),
(33039, 'Luke 5:33', 'Luke', 5, 33, 'ځینو خلکو عیسی ته وویل: «د یحیی شاګردان زیات وخت روژه نیسي او دعاګانې کوي او د فریسیانو شاګردان هم همداسې کوي، خو ستا شاګردان خوري او څښي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_33.mp3', '', 1761754199, 1761754199),
(33040, 'Luke 5:34', 'Luke', 5, 34, 'عیسی ځواب ورکړ: «ایا تاسو کولای شئ چې د زوم ملګري د واده په مېلمستیا کې په داسې حال کې چې زوم ورسره وي مجبور کړئ چې روژه ونیسي؟ بې له شکه چې نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_34.mp3', '', 1761754199, 1761754199),
(33041, 'Luke 5:35', 'Luke', 5, 35, 'خو داسې وخت به راشي چې زوم به له هغوی څخه بوتلل شي او په هغه وخت کې به هغوی روژه نیسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_35.mp3', '', 1761754199, 1761754199),
(33042, 'Luke 5:36', 'Luke', 5, 36, 'همدارنګه عیسی هغوی ته دا مثال راوړ: «هېڅوک د نویو کالیو څخه یوه ټوټه نه شلوي چې په زړو کالیو باندې یې پیوند کړي. که داسې وکړي، نو هم به هغه نوي کالي وشلیږي او هم به د نویو کالیو ټوټه د زړې ټوټې سره جوړه رانه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_36.mp3', '', 1761754199, 1761754199),
(33043, 'Luke 5:37', 'Luke', 5, 37, 'نه به څوک تازه شراب په زړو مشکونو کې واچوي، ځکه چې تازه شراب به هغه مشکونه وشلوي، شراب به توی شي او مشکونه به له منځه لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_37.mp3', '', 1761754199, 1761754199),
(33044, 'Luke 5:38', 'Luke', 5, 38, 'خو تازه شراب باید په نویو مشکونو کې واچول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_38.mp3', '', 1761754199, 1761754199),
(33045, 'Luke 5:39', 'Luke', 5, 39, 'هېڅوک نه غواړي چې د زړو شرابو له څښلو وروسته تازه شراب وڅښي، ځکه داسې وایي چې زاړه شراب ډېر ښه دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke5_verse_39.mp3', '', 1761754199, 1761754199),
(33046, 'Colossians 2:1', 'Colossians', 2, 1, 'نو زه غواړم چې تاسو پوه شئ چې زه ستاسو دپاره او د خدای د هغو خلکو دپاره چې په لایودیکیه کې دي او د هغو ټولو دپاره چې تر‌اوسه پورې یې زما مخ نه دی لیدلی، څومره ډېر زحمت وباسم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_1.mp3', '', 1761754199, 1761754199),
(33047, 'Colossians 2:2', 'Colossians', 2, 2, 'ترڅو هغوی زړور شي او د مینې په تار یو د بل سره وګنډل شي او د ارزښت نه ډکې پوهې باندې پوره باور ولري او د خدای په پټ راز چې خپله مسیح دی، پوه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_2.mp3', '', 1761754199, 1761754199),
(33048, 'Colossians 2:3', 'Colossians', 2, 3, 'په هغه کې د حکمت او پوهې ټولې خزانې پټې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_3.mp3', '', 1761754199, 1761754199),
(33049, 'Colossians 2:4', 'Colossians', 2, 4, 'زه دا تاسو ته د دې دپاره وایم چې څوک مو په داسې دلیلونو باندې چې په ظاهره معقول ښکاري ونه غولوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_4.mp3', '', 1761754199, 1761754199),
(33050, 'Colossians 2:5', 'Colossians', 2, 5, 'ځکه که څه هم زه په جسماني توګه ستاسو نه لېرې یم، خو په روحاني توګه ستاسو سره یم. زه خوشحاله یم چې تاسو وینم چې په خپل منځ کې په څومره ښه نظم او ترتیب ژوند تېروئ او په مسیح باندې ستاسو ایمان څومره قوي دی. په مسیح کې کامل ژوند', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_5.mp3', '', 1761754199, 1761754199),
(33051, 'Colossians 2:6', 'Colossians', 2, 6, 'نو لکه څنګه چې تاسو عیسی مسیح د خپل څښتن په توګه قبول کړ، نو د هغه سره په یووالي کې خپل ژوند کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_6.mp3', '', 1761754199, 1761754199),
(33052, 'Colossians 2:7', 'Colossians', 2, 7, 'په هغه کې خپلې ریښې وځغلوئ او په هغه باندې خپل ژوند جوړ کړئ. لکه څنګه چې درته تعلیم درکړل شوی دی، په خپل ایمان کې ټینګ اوسئ او ډېره شکرګزاري کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_7.mp3', '', 1761754199, 1761754199),
(33053, 'Colossians 2:8', 'Colossians', 2, 8, 'پام کوئ چې څوک مو په پوچو فلسفو سره چې خلک غولوي راګېر نه کړي، ځکه چې دا د انساني رواجونو او د دې دنیا د بدو روحاني قوتونو سره تړلي دي، نه د مسیح سره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_8.mp3', '', 1761754199, 1761754199),
(33054, 'Colossians 2:9', 'Colossians', 2, 9, 'ځکه چې مسیح په انساني جسم کې د خدای کامل خوی او فطرت لري', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_9.mp3', '', 1761754199, 1761754199),
(33055, 'Colossians 2:10', 'Colossians', 2, 10, 'او تاسو هم په هغه کې چې د ټولو حکومتونو او د واک خاوندانو سر دی، کامل شوي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_10.mp3', '', 1761754199, 1761754199),
(33056, 'Colossians 2:11', 'Colossians', 2, 11, 'تاسو د مسیح سره په یووالي کې سنت شوئ، خو دا سنتېدل د انسان په لاس نه دي شوي، بلکې مسیح تاسو په روحاني توګه سنت کړئ، ترڅو ستاسو نفساني فطرت لېرې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_11.mp3', '', 1761754199, 1761754199),
(33057, 'Colossians 2:12', 'Colossians', 2, 12, 'کله چې تاسو د تعمید غسل واخیست، نو د مسیح سره ښخ شوئ او ستاسو د ایمان په وسیله د خدای په قدرت سره چې مسیح یې بېرته راژوندی کړ، تاسو هم د هغه سره په روحاني توګه د مړو نه راپورته شوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_12.mp3', '', 1761754199, 1761754199),
(33058, 'Colossians 2:13', 'Colossians', 2, 13, 'تاسو یو وخت د خپلو سرغړونو او له دې امله چې په جسماني توګه ناسنته وئ، مړه وئ نو بیا خدای تاسو د مسیح سره یوځای د مړو نه راپورته کړئ او ستاسو ټول ګناهونه یې وبخښل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_13.mp3', '', 1761754199, 1761754199),
(33059, 'Colossians 2:14', 'Colossians', 2, 14, 'خدای هغه ټول ثبت شوي تورونه چې د قانون څخه د نافرمانۍ له امله په مونږ لګېدلي وو، پاک کړل. هغه یې په صلیب باندې مېخ کړل او لېرې یې کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_14.mp3', '', 1761754199, 1761754199),
(33060, 'Colossians 2:15', 'Colossians', 2, 15, 'مسیح حاکمان او د واک خاوندان بې‌وسلې کړل او هغوی یې د ټولو په مخکې رسوا کړل او د صلیب په وسیله په ټولو باندې بریالی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_15.mp3', '', 1761754199, 1761754199),
(33061, 'Colossians 2:16', 'Colossians', 2, 16, 'نو له دې امله هېچا ته اجازه مه ورکوئ چې د خوراک څښاک یا د اختر یا د نوې میاشتې او یا د سبت د ورځې د مراعت کولو په هکله په تاسو حکم او قضاوت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_16.mp3', '', 1761754199, 1761754199),
(33062, 'Colossians 2:17', 'Colossians', 2, 17, 'دا شیان یوازې د هغه حقیقت سیوری دی چې راتلونکی دی او دا حقیقت په خپله مسیح دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_17.mp3', '', 1761754199, 1761754199),
(33063, 'Colossians 2:18', 'Colossians', 2, 18, 'مه پرېږدئ چې څوک په ظاهري عاجزۍ او د فرښتو په عبادت کولو سره تاسو د اجر او انعام د اخیستلو څخه بې‌برخې کړي. داسې خلک د رویاګانو د لیدلو په تفصیلي بیان او خپلو انساني فکرونو سره بېځایه غرور کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_18.mp3', '', 1761754199, 1761754199),
(33064, 'Colossians 2:19', 'Colossians', 2, 19, 'هغوی د مسیح سره چې د ټول بدن سر دی، خپلې اړیکې پریښي دي. د هغه په وسیله ټول بدن قوت اخلي او ټول بندونه او پلې سره یوځای کیږي او لکه څنګه چې خدای یې غواړي، هغه وده کوي. د مسیح سره مړ کېدل او بېرته را ژوندی کېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_19.mp3', '', 1761754199, 1761754199),
(33065, 'Colossians 2:20', 'Colossians', 2, 20, 'کله چې تاسو د مسیح سره مړه شوئ، نو د دې دنیا د بدو روحاني قدرتونو څخه هم ازاد شوئ، نو بیا ولې داسې ژوند تېروئ چې ګواکې اوس هم د دنیا سره تړاو لرئ؟ ولې داسې مقرراتو ته غاړه ږدئ لکه څنګه چې هغوی وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_20.mp3', '', 1761754199, 1761754199),
(33066, 'Colossians 2:21', 'Colossians', 2, 21, '«دا په لاس کې مه اخلئ، دا مه څکئ، دې ته لاس مه وروړئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_21.mp3', '', 1761754199, 1761754199),
(33067, 'Colossians 2:22', 'Colossians', 2, 22, 'کله چې دا ټول شیان وکارول شي نو له منځه ځي، ځکه چې دا یوازې انساني حکمونه او تعلیمونه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_22.mp3', '', 1761754199, 1761754199),
(33068, 'Colossians 2:23', 'Colossians', 2, 23, 'که څه هم دا شیان په هغو عبادتونو کې چې هغوی په خپلو ځانونو باندې منلي دي او ظاهري عاجزي او په ځان سختي راوستل په ظاهره معقول ښکاري، خو په حقیقت کې دا شیان نه شي کولای چې د نفساني غوښتنو مخه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians2_verse_23.mp3', '', 1761754199, 1761754199),
(33069, 'Matthew 1:1', 'Matthew', 1, 1, 'د عیسی مسیح شجره چې هغه د داود پاچا د کورنۍ او د ابراهیم د اولادې څخه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_1.mp3', '', 1761754199, 1761754199),
(33070, 'Matthew 1:2', 'Matthew', 1, 2, 'ابراهیم د اسحاق پلار ؤ او اسحاق د یعقوب پلار ؤ او یعقوب د یهودا او د هغه د ورونو پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_2.mp3', '', 1761754199, 1761754199),
(33071, 'Matthew 1:3', 'Matthew', 1, 3, 'او یهودا د فارز او زارح پلار ؤ چې مور یې تامار وه او فارز د حزرون پلار ؤ او حزرون د آرام پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_3.mp3', '', 1761754199, 1761754199),
(33072, 'Matthew 1:4', 'Matthew', 1, 4, 'او آرام د عمیناداب پلار ؤ او عمیناداب د نحشون پلار ؤ او نحشون د شلمون پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_4.mp3', '', 1761754199, 1761754199),
(33073, 'Matthew 1:5', 'Matthew', 1, 5, 'او شلمون د بوعز پلار ؤ چې مور یې راحاب وه او بوعز د عوبید پلار ؤ چې مور یې روت وه او عوبید د یسي پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_5.mp3', '', 1761754199, 1761754199),
(33074, 'Matthew 1:6', 'Matthew', 1, 6, 'او یسي د داود پاچا پلار ؤ. داود د سلیمان پلار ؤ او د سلیمان مور د اوریا پخوانۍ ښځه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_6.mp3', '', 1761754199, 1761754199),
(33075, 'Matthew 1:7', 'Matthew', 1, 7, 'او سلیمان د رحبعام پلار ؤ او رحبعام د ابیا پلار ؤ او ابیا د آسا پلار ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_7.mp3', '', 1761754199, 1761754199),
(33076, 'Matthew 1:8', 'Matthew', 1, 8, 'آسا د یهوشافاط پلار ؤ او یهوشافاط د یورام پلار ؤ او یورام د عزیا پلار ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_8.mp3', '', 1761754199, 1761754199),
(33077, 'Matthew 1:9', 'Matthew', 1, 9, 'عزیا د یوتام پلار ؤ او یوتام د آحاز پلار ؤ او آحاز د حزقیا پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_9.mp3', '', 1761754199, 1761754199),
(33078, 'Matthew 1:10', 'Matthew', 1, 10, 'او حزقیا د منسي پلار ؤ او منسي د آمون پلار ؤ او آمون د یوشیا پلار ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_10.mp3', '', 1761754199, 1761754199),
(33079, 'Matthew 1:11', 'Matthew', 1, 11, 'یوشیا د یکنیا او د هغه د ورونو پلار ؤ. په دې وخت کې یهودیان بابل ته جلاوطن شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_11.mp3', '', 1761754199, 1761754199),
(33080, 'Matthew 1:12', 'Matthew', 1, 12, 'بابل ته د یهودیانو د جلاوطنۍ نه وروسته یکنیا د شالتي‌ییل پلار ؤ او شالتي‌ییل د زروبابل پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_12.mp3', '', 1761754199, 1761754199),
(33081, 'Matthew 1:13', 'Matthew', 1, 13, 'او زروبابل د آبیهود پلار ؤ او آبیهود د ایلیاقیم او الیاقیم د عازور پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_13.mp3', '', 1761754199, 1761754199),
(33082, 'Matthew 1:14', 'Matthew', 1, 14, 'او عازور د صادوق پلار او صادوق د یاکین او یاکین د ایلیهود پلار ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_14.mp3', '', 1761754199, 1761754199),
(33083, 'Matthew 1:15', 'Matthew', 1, 15, 'او ایلیهود د العازار پلار او العازار د متان پلار ؤ او متان د یعقوب پلار', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_15.mp3', '', 1761754199, 1761754199),
(33084, 'Matthew 1:16', 'Matthew', 1, 16, 'او یعقوب د یوسف پلار ؤ چې یوسف د مریمې مېړه ؤ او مریم عیسی وزېږاوه چې مسیح به یې ورته ویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_16.mp3', '', 1761754199, 1761754199),
(33085, 'Matthew 1:17', 'Matthew', 1, 17, 'نو په دې ډول د ابراهیم څخه تر داود پورې څوارلس نسلونه او د داود څخه بابل ته د یهودیانو د جلاوطنۍ تر وخته پورې څوارلس نسلونه او د جلاوطنۍ د وخت څخه تر مسیح پورې څوارلس نسلونه کیږي. د عیسی زېږېدنه (لوقا ۲‏:‌۱‌‏-‌۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_17.mp3', '', 1761754199, 1761754199),
(33086, 'Matthew 1:18', 'Matthew', 1, 18, 'د عیسی مسیح زېږېدنه داسې وه: کله چې د هغه د مور مریم کوژدنه د یوسف سره وشوه نو مخکې له دې چې د هغوی واده وشي، معلومه شوه چې هغه د روح القدس په وسیله امیدواره وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_18.mp3', '', 1761754199, 1761754199),
(33087, 'Matthew 1:19', 'Matthew', 1, 19, 'یوسف چې یو نېک سړی ؤ او نه یې غوښتل چې مریم د خلکو په مخکې رسوا شي، نو پرېکړه یې وکړه چې په پټه هغې ته طلاق ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_19.mp3', '', 1761754199, 1761754199),
(33088, 'Matthew 1:20', 'Matthew', 1, 20, 'یوسف لا په دې هکله فکر کاوه چې د څښتن یوه فرښته ورته په خوب کې ښکاره شوه او ویې ویل: «ای د داود زویه یوسفه! د مریم سره د واده کولو نه مه وېرېږه، ځکه چې هغه د روح القدس په وسیله امیدواره شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_20.mp3', '', 1761754199, 1761754199),
(33089, 'Matthew 1:21', 'Matthew', 1, 21, 'د هغې به زوی وشي او ته ورباندې عیسی نوم کېږده، ځکه چې هغه به خپل قوم د ګناهونو څخه وژغوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_21.mp3', '', 1761754199, 1761754199),
(33090, 'Matthew 1:22', 'Matthew', 1, 22, 'دا هرڅه ځکه وشول، ترڅو څه چې څښتن د خپل پیغمبر په وسیله ویلي وو هغه رښتیا شي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_22.mp3', '', 1761754199, 1761754199),
(33091, 'Matthew 1:23', 'Matthew', 1, 23, 'ګورئ، یوه پېغله به امیدواره شي او هغه به یو زوی وزېږوي او هغوی به په هغه باندې عمانوییل نوم کېږدي. (د عمانوییل معنی ده خدای زمونږ سره مل دی.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_23.mp3', '', 1761754199, 1761754199),
(33092, 'Matthew 1:24', 'Matthew', 1, 24, 'کله چې یوسف له خوبه راویښ شو، نو څنګه چې د څښتن فرښتې ورته حکم کړی ؤ هماغسې یې وکړل او د مریم سره یې واده وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_24.mp3', '', 1761754199, 1761754199),
(33093, 'Matthew 1:25', 'Matthew', 1, 25, 'خو تر هغې پورې چې د هغې زوی پیدا شوی نه ؤ یوسف ورسره یوځای نه شو او په هغه باندې یې عیسی نوم کېښود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew1_verse_25.mp3', '', 1761754199, 1761754199),
(33094, 'Hebrews 1:1', 'Hebrews', 1, 1, 'خدای په تېره زمانه کې څو څو ځلې په مختلفو طریقو سره د خپلو پیغمبرانو په وسیله زمونږ د نیکونو سره خبرې کړې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_1.mp3', '', 1761754199, 1761754199),
(33095, 'Hebrews 1:2', 'Hebrews', 1, 2, 'خو په دې اخرنیو ورځو کې یې د خپل زوی په وسیله زمونږ سره خبرې کړې دي. هغه زوی چې خدای د ټولو شیانو وارث ټاکلی دی او د هغه په وسیله یې نړۍ پیدا کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_2.mp3', '', 1761754199, 1761754199),
(33096, 'Hebrews 1:3', 'Hebrews', 1, 3, 'هغه د خدای د جلال ښکاره کوونکی او د هغه د کامل ذات تصویر دی او هغه ټول کاینات د خپل کلام د قدرت په وسیله ساتي. کله چې هغه خلکو ته د خپلو ګناهونو څخه د بخښنې لاره جوړه کړه، نو هغه په اسمان کې د مطلق قادر خدای ښي لاس ته کښېناست. مسیح د فرښتو نه لوی دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_3.mp3', '', 1761754199, 1761754199),
(33097, 'Hebrews 1:4', 'Hebrews', 1, 4, 'څرنګه چې مسیح د فرښتو نه ډېر لوی دی، نو خدای چې هغه ته کوم نوم ورکړی دی، هغه هم د هغوی د نومونو نه ډېر لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_4.mp3', '', 1761754199, 1761754199),
(33098, 'Hebrews 1:5', 'Hebrews', 1, 5, 'ځکه چې خدای هېڅکله کومې فرښتې ته نه دي ویلي: ته مې زوی، زه دې نن پلار شوم. او یا دا: زه به یم د هغه پلار او هغه وي به زما زوی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_5.mp3', '', 1761754199, 1761754199),
(33099, 'Hebrews 1:6', 'Hebrews', 1, 6, 'خو کله چې خدای لومړنی زېږېدلی نړۍ ته راولي، نو ورته وایي: د خدای ټولې فرښتې دې د هغه عبادت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_6.mp3', '', 1761754199, 1761754199),
(33100, 'Hebrews 1:7', 'Hebrews', 1, 7, 'خو د فرښتو په هکله وایي: خدای رالېږي خپلې فرښتې لکه بادونو په شان او خپل خدمتګاران لکه د اور د لمبو په شان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_7.mp3', '', 1761754199, 1761754199),
(33101, 'Hebrews 1:8', 'Hebrews', 1, 8, 'خو د خپل زوی په هکله وایي: ای خدایه! تل ترتله به وي ستا د پاچاهۍ تخت او کړې به حکومت په خپلو خلکو باندې د انصاف له مخې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_8.mp3', '', 1761754199, 1761754199),
(33102, 'Hebrews 1:9', 'Hebrews', 1, 9, 'ته خوښوې عدالت او کرکه کوې له بدۍ په دې خاطر خدای، یعنې ستا خدای ته یې ستا د نورو ملګرو نه زیات مسح کړی یې د خوشحالۍ په تېلو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_9.mp3', '', 1761754199, 1761754199),
(33103, 'Hebrews 1:10', 'Hebrews', 1, 10, 'همدارنګه هغه وایي: ای څښتنه، له شروع څخه دې ایښی ؤ بنیاد د ځمکې او اسمانونه دې کړل جوړ خپلو لاسونو باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_10.mp3', '', 1761754199, 1761754199),
(33104, 'Hebrews 1:11', 'Hebrews', 1, 11, 'هغوی فنا به شي، خو ته به پاتې شې هغوی به ټول زاړه شي لکه لباس په شان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_11.mp3', '', 1761754199, 1761754199),
(33105, 'Hebrews 1:12', 'Hebrews', 1, 12, 'تاو راتاو به کړې هغوی لکه چپنې په شان او بدل به یې کړې لکه لباس په شان خو پاتې کېږې په خپل حال ته مدام او پای به ونه لري هېڅ دا ستا دوران', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_12.mp3', '', 1761754199, 1761754199),
(33106, 'Hebrews 1:13', 'Hebrews', 1, 13, 'خو خدای هېڅکله هم کومې فرښتې ته نه دي ویلي: کښېنه زما ښي لاس ته ترڅو کړم ستا دښمنان ستا د پښو لاندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_13.mp3', '', 1761754199, 1761754199),
(33107, 'Hebrews 1:14', 'Hebrews', 1, 14, 'ایا ټولې فرښتې خدمتګار روحونه نه دي چې د هغو خلکو د خدمت دپاره رالېږل شوي چې خلاصون به مومي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews1_verse_14.mp3', '', 1761754199, 1761754199),
(33108, 'Luke 17:1', 'Luke', 17, 1, 'عیسی خپلو شاګردانو ته وویل: «هرڅوک وسوسه کیږي چې ګناه وکړي، خو افسوس د هغه چا په حال چې د وسوسې سبب کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_1.mp3', '', 1761754199, 1761754199),
(33109, 'Luke 17:2', 'Luke', 17, 2, 'د هغه دپاره به دا ښه وي چې د ژرندې پل ورته په غاړه کې واچول شي او بحیرې ته وغورځول شي، له دې نه چې د دې خلکو څخه چې د ماشوم په شان په ما باندې ایمان لري، د کوم یو د ګناهکارولو سبب شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_2.mp3', '', 1761754199, 1761754199),
(33110, 'Luke 17:3', 'Luke', 17, 3, 'پام کوئ! که چېرې ورور دې درسره بدي وکړي، نو هغه ورټه او که توبه وباسي، نو ویې بخښه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_3.mp3', '', 1761754199, 1761754199);